gZJ(){return"\u062a\u0628\u0642\u0649 \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0641\u064a\u0647 \u0648\u062a\u0646\u062a\u0642\u0644 \u0625\u0644\u0649 \xab\u0628\u062f\u0648\u0646 \u062a\u0635\u0646\u064a\u0641\xbb."},
gac_(){return"\u062d\u0635\u0631 \u0627\u0644\u0645\u0648\u0638\u0641 \u0641\u064a \u062a\u0635\u0646\u064a\u0641\u0627\u062a \u0623\u0646\u0648\u0627\u0639 \u0627\u0644\u062d\u0627\u0644\u0627\u062a"},
gabZ(){return"\u0627\u062a\u0631\u0643\u0647 \u0641\u0627\u0631\u063a\u064b\u0627 \u0644\u0644\u0648\u0635\u0648\u0644 \u0627\u0644\u0643\u0627\u0645\u0644. \u0627\u062e\u062a\u0631 \u062a\u0635\u0646\u064a\u0641\u064b\u0627 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0648\u0633\u064a\u0631\u0649 \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0638\u0641 \u0648\u064a\u0639\u0645\u0644 \u0641\u0642\u0637 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0627\u0644\u062a\u0627\u0628\u0639\u0629 \u0644\u0647\u0627 \u0641\u064a \u0643\u0644 \u0623\u062c\u0632\u0627\u0621 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0627\u0644\u0645\u062f\u064a\u0631 \u0644\u0627 \u064a\u062a\u0623\u062b\u0631 \u0628\u0647\u0630\u0627 \u0627\u0644\u062d\u0635\u0631. \u0644\u0627 \u062a\u0645\u0646\u062d \u0627\u0644\u0645\u0648\u0638\u0641 \u0627\u0644\u0645\u062d\u0635\u0648\u0631 \u0635\u0644\u0627\u062d\u064a\u0629 \u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0623\u0648 \u0627\u0644\u062a\u0642\u0627\u0631\u064a\u0631\u060c \u0641\u0633\u062a\u0634\u0645\u0644 \u0623\u0631\u0642\u0627\u0645\u0647 \u0647\u0630\u0647 \u0627\u0644\u062a\u0635\u0646\u064a\u0641\u0627\u062a \u0641\u0642\u0637."},
P3(a,b){return"\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u0645\u0633\u062a\u062e\u062f\u0645\u0629: "+a+" \u0645\u0646 "+b+" \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0645\u062c\u0627\u0646\u064a\u0629"},
P2(a,b,c){return""+a+" \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0645\u0634\u0645\u0648\u0644\u0629. \u0628\u0639\u062f\u0647\u0627 "+b+" \u0644\u0643\u0644 100 \u063a\u064a\u063a\u0627\u0628\u0627\u064a\u062a \u0633\u0646\u0648\u064a\u0627\u064b\u060c \u062d\u0633\u0628 \u0645\u062a\u0648\u0633\u0637 \u0627\u0633\u062a\u062e\u062f\u0627\u0645\u0643 \u062e\u0644\u0627\u0644 \u0622\u062e\u0631 12 \u0634\u0647\u0631\u0627\u064b ("+c+" \u062d\u0627\u0644\u064a\u0627\u064b)."},
P1(a){return"\u0631\u0633\u0648\u0645 \u0627\u0644\u062a\u062e\u0632\u064a\u0646 \u0627\u0644\u0645\u062a\u0648\u0642\u0639\u0629 \u0647\u0630\u0647 \u0627\u0644\u0633\u0646\u0629: "+a},
gYq(){return"\u0625\u0631\u0633\u0627\u0644"},
Yr(a){return"\u0623\u064f\u0631\u0633\u0644\u062a "+a},
