Gp(a,b){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0647\u0630\u0647 \u0627\u0644\u062d\u0627\u0644\u0629 \u0625\u0644\u0649 "+a+" \u0641\u064a "+b+". \u0647\u0644 \u062a\u0631\u064a\u062f \u0625\u0631\u0633\u0627\u0644\u0647\u0627 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649\u061f"},
gYn(){return"\u0625\u0631\u0633\u0627\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649"},
gY_(){return"\u0625\u0631\u0633\u0627\u0644 \u0625\u0644\u0649"},
Ys(a){return"\u0623\u064f\u0631\u0633\u0644\u062a \u0625\u0644\u0649 "+a},
Yp(a){return"\u062a\u0639\u0630\u0651\u0631 \u0627\u0644\u0625\u0631\u0633\u0627\u0644: "+a},
gafB(){return"\u062c\u0647\u0627\u062a \u0627\u0644\u0627\u062a\u0635\u0627\u0644 (\u0627\u0644\u0645\u0637\u0628\u0639\u0629\u060c \u0645\u062e\u062a\u0628\u0631 \u0627\u0644\u062e\u0631\u0627\u0637\u0629\u2026)"},
gafA(){return"\u0632\u0631 \xab\u0625\u0631\u0633\u0627\u0644\xbb \u0641\u064a \u0635\u0641\u062d\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u064a\u0631\u0633\u0644 \u0648\u0631\u0642\u0629 \u0627\u0644\u062d\u0627\u0644\u0629 \u0625\u0644\u0649 \u0645\u062d\u0627\u062f\u062b\u0627\u062a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0647\u0630\u0647 \u0628\u0636\u063a\u0637\u0629 \u0648\u0627\u062d\u062f\u0629."},
gafz(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u062c\u0647\u0627\u062a \u0627\u062a\u0635\u0627\u0644 \u0628\u0639\u062f."},
gK3(){return"\u0625\u0636\u0627\u0641\u0629 \u062c\u0647\u0629 \u0627\u062a\u0635\u0627\u0644"},
gafu(){return"\u0627\u0644\u0627\u0633\u0645 (\u0645\u062b\u0644\u0627\u064b: \u0627\u0644\u0645\u0637\u0628\u0639\u0629)"},
gafr(){return"\u0625\u0646\u0634\u0627\u0621 \u0631\u0627\u0628\u0637"},
gaft(){return"\u0623\u0631\u0633\u0644 \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0625\u0644\u0649 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644. \u064a\u0641\u062a\u062d\u0647 \u0641\u064a \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0648\u064a\u0636\u063a\u0637 \xab\u0627\u0628\u062f\u0623\xbb \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629. \u064a\u0639\u0645\u0644 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0641\u0642\u0637 \u0648\u062e\u0644\u0627\u0644 24 \u0633\u0627\u0639\u0629."},
gafs(){return"\u0623\u0648\u060c \u0644\u062a\u0631\u0649 \u0643\u0644 \u0648\u0631\u0642\u0629 \u062a\u0631\u0633\u0644\u0647\u0627: \u0623\u0646\u0634\u0626 \u0645\u062c\u0645\u0648\u0639\u0629 \u062a\u064a\u0644\u064a\u062c\u0631\u0627\u0645 \u0645\u0639 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644\u060c \u062b\u0645 \u0627\u0641\u062a\u062d \u0647\u0630\u0627 \u0627\u0644\u0631\u0627\u0628\u0637 \u0648\u0627\u062e\u062a\u0631 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629. \u0633\u062a\u0635\u0644 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0625\u0644\u0649 \u0627\u0644\u0645\u062c\u0645\u0648\u0639\u0629 \u0623\u0645\u0627\u0645\u0643\u0645\u0627 \u0645\u0639\u0627\u064b. \u0627\u0633\u062a\u062e\u062f\u0645 \u0631\u0627\u0628\u0637\u0627\u064b \u0648\u0627\u062d\u062f\u0627\u064b \u0641\u0642\u0637 \u0645\u0646 \u0627\u0644\u0627\u062b\u0646\u064a\u0646."},
afv(a,b){return a+" \xb7 \u0628\u0627\u0646\u062a\u0638\u0627\u0631 \xab\u0627\u0628\u062f\u0623\xbb (\u0627\u0644\u0631\u0627\u0628\u0637 \u0635\u0627\u0644\u062d \u062d\u062a\u0649 "+b+")"},
gafw(){return"\u0625\u0632\u0627\u0644\u0629"},
gafy(){return"\u0625\u0632\u0627\u0644\u0629 \u062c\u0647\u0629 \u0627\u0644\u0627\u062a\u0635\u0627\u0644 \u0647\u0630\u0647\u061f"},
afx(a){return"\u0644\u0646 \u062a\u0635\u0644 \u0623\u0648\u0631\u0627\u0642 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0625\u0644\u0649 \xab"+a+"\xbb \u0628\u0639\u062f \u0627\u0644\u0622\u0646. \u064a\u0645\u0643\u0646\u0643 \u0625\u0636\u0627\u0641\u062a\u0647\u0627 \u0645\u062c\u062f\u062f\u0627\u064b \u0628\u0631\u0627\u0628\u0637 \u062c\u062f\u064a\u062f."},
gNt(){return"\u062a\u0635\u062f\u064a\u0631 \u0628\u064a\u0627\u0646\u0627\u062a\u064a"},
gNu(){return"\u0646\u0633\u062e\u0629 \u0643\u0627\u0645\u0644\u0629 \u0645\u0646 \u0628\u064a\u0627\u0646\u0627\u062a \u0645\u062e\u062a\u0628\u0631\u0643 \u0639\u0644\u0649 \u062c\u0647\u0627\u0632\u0643 \u0627\u0644\u062e\u0627\u0635 \u2014 \u0644\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0628\u0647\u0627 \u0648\u0644\u0642\u0631\u0627\u0621\u062a\u0647\u0627 \u0628\u062f\u0648\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0648\u0628\u062f\u0648\u0646 \u0625\u0646\u062a\u0631\u0646\u062a."},
ga2T(){return"\u062a\u062d\u0635\u0644 \u0639\u0644\u0649 \u0645\u0644\u0641 \u0645\u0636\u063a\u0648\u0637 (zip) \u0641\u064a\u0647 \u0627\u0644\u062d\u0627\u0644\u0627\u062a \u0648\u0627\u0644\u0645\u062f\u0641\u0648\u0639\u0627\u062a \u0648\u0627\u0644\u0623\u0631\u0635\u062f\u0629 \u0648\u0627\u0644\u062a\u0643\u0627\u0644\u064a\u0641 \u0648\u0627\u0644\u0631\u0648\u0627\u062a\u0628 \u0648\u0627\u0644\u0645\u0648\u0631\u062f\u064a\u0646 \u0648\u063a\u064a\u0631\u0647\u0627 \u0643\u062c\u062f\u0627\u0648\u0644 (\u0645\u0644\u0641\u0627\u062a CSV \u062a\u064f\u0641\u062a\u062d \u0641\u064a Excel)\u060c \u0648\u0635\u0641\u062d\u0629 \u0627\u0633\u0645\u0647\u0627 index.html \u062a\u064f\u0641\u062a\u062d \u0641\u064a \u0623\u064a \u0645\u062a\u0635\u0641\u062d \u0645\u0639 \u062e\u0627\u0635\u064a\u0629 \u0627\u0644\u0628\u062d\u062b\u060c \u0628\u062f\u0648\u0646 \u0625\u0646\u062a\u0631\u0646\u062a \u0648\u0628\u062f\u0648\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642. \u0641\u0643 \u0627\u0644\u0636\u063a\u0637 \u062b\u0645 \u0627\u0646\u0642\u0631 \u0645\u0631\u062a\u064a\u0646 \u0639\u0644\u0649 index.html."},
ga2I(){return"\u062a\u0636\u0645\u064a\u0646 \u0627\u0644\u0635\u0648\u0631 \u0648\u0627\u0644\u0645\u0644\u0641\u0627\u062a"},
a2J(a,b){return"\u062d\u0648\u0627\u0644\u064a "+a+" ("+b+" \u0645\u0644\u0641). \u062a\u064f\u062d\u0641\u0638 \u0639\u0644\u0649 \u0639\u062f\u0629 \u0623\u062c\u0632\u0627\u0621 \u0645\u0636\u063a\u0648\u0637\u0629 \u2014 \u0641\u0643 \u0636\u063a\u0637\u0647\u0627 \u0643\u0644\u0647\u0627 \u0641\u064a \u0646\u0641\u0633 \u0645\u062c\u0644\u062f \u0645\u0644\u0641 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u062d\u062a\u0649 \u062a\u0639\u0645\u0644 \u0627\u0644\u0631\u0648\u0627\u0628\u0637 \u0641\u064a index.html."},
