ga0M(){return"\u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0646\u0631\u062e \u0628\u06c6 \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5"},
ga0n(){return"\u0646\u0627\u0686\u0627\u0644\u0627\u06a9\u06a9\u0631\u062f\u0646\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
