ga3s(){return"\u062e\u0627\u0646\u06d5\u06a9\u06d5 \u0628\u06d5\u062a\u0627\u06b5 \u0628\u0647\u06ce\u06b5\u06d5\u0631\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u06d5\u06a9\u0627\u0631\u0647\u06ce\u0646\u0627\u0646\u06cc \u0646\u0631\u062e\u06cc \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc \u0645\u0627\u062f\u062f\u06d5\u06a9\u06d5. \u0646\u0631\u062e\u06cc \u067e\u0627\u0634\u06d5\u06a9\u06d5\u0648\u062a\u06a9\u0631\u0627\u0648 \u062a\u06d5\u0646\u0647\u0627 \u0628\u06c6 \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u062f\u06d5\u0628\u06ce\u062a."},
a3r(a){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc "+a},
ga3v(){return"\u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
ga3u(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u06cc\u06d5\u06a9\u06d5\u0645"},
ga3q(){return"\u06cc\u06d5\u06a9\u06d5\u06cc \u0632\u06cc\u0627\u062a\u0631"},
ga3A(){return"\u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5 \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5 \u067e\u06ce\u0634\u0648\u0648\u06d5\u06a9\u0627\u0646 \u062c\u06ce\u0628\u06d5\u062c\u06ce \u0628\u06a9\u0631\u06ce\u062a\u061f"},
a3y(a){return""+a+" \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u0626\u06d5\u0645 \u067e\u0632\u06cc\u0634\u06a9\u06d5 \u0646\u0631\u062e\u06cc\u0627\u0646 \u062f\u06d5\u06af\u06c6\u0695\u06ce\u062a \u0628\u06d5 \u0646\u0631\u062e\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u06d5. \u0646\u06cc\u0634\u0627\u0646\u06d5\u06cc \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0644\u0627\u0628\u06d5 \u0628\u06c6 \u0626\u06d5\u0648\u06d5\u06cc \u0646\u0631\u062e\u06cc \u0626\u06ce\u0633\u062a\u0627\u06cc \u0628\u0645\u06ce\u0646\u06ce\u062a. \u06a9\u06d5\u06cc\u0633\u06cc \u067e\u0627\u0631\u06d5\u062f\u0631\u0627\u0648\u060c \u062f\u0648\u0648\u0628\u0627\u0631\u06d5\u06a9\u0631\u0627\u0648\u06d5 \u0648 \u0647\u06d5\u06b5\u0648\u06d5\u0634\u0627\u0648\u06d5 \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u0627\u06af\u06c6\u0695\u06ce\u0646."},
ga3z(){return"\u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5 \u0646\u0648\u06ce\u06cc\u06d5\u06a9\u0627\u0646"},
a3w(a){return"\u0646\u0648\u06ce\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc "+a+" \u06a9\u06d5\u06cc\u0633"},
