ga4M(){return"\u0632\u06cc\u0627\u062f\u06a9\u0631\u062f\u0646\u06cc \u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
ga4D(){return"\u06cc\u0627\u0633\u0627\u06cc \u067e\u0632\u06cc\u0634\u06a9"},
ga4E(){return"\u067e\u0632\u06cc\u0634\u06a9"},
ga4L(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633"},
gHJ(){return"\u0647\u06d5\u0645\u0648\u0648 \u062c\u06c6\u0631\u06d5\u06a9\u0627\u0646"},
