gN_(){return"\u0633\u06a9\u0627\u0646\u06a9\u0631\u062f\u0646\u06cc QR \u0644\u06d5 \u0648\u06ce\u0646\u06d5\u06a9\u0627\u0646\u06d5\u0648\u06d5"},
gN0(){return"\u067e\u06d5\u0646\u062c\u06d5\u0631\u06d5\u06cc \xab\u0633\u06a9\u0627\u0646\u06a9\u0631\u062f\u0646\u06cc QR\xbb \u0644\u06d5 \u0628\u06c6\u0631\u062f \u062f\u0648\u06af\u0645\u06d5\u06cc \xab\u0644\u06d5 \u0648\u06ce\u0646\u06d5\u06a9\u0627\u0646\u06d5\u0648\u06d5\xbb \u067e\u06cc\u0634\u0627\u0646 \u062f\u06d5\u062f\u0627\u062a: \u0648\u06ce\u0646\u06d5\u06cc \u0644\u06d5\u06cc\u0628\u06b5\u06cc \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646 \u0644\u06d5 \u06af\u06d5\u0644\u06d5\u0631\u06cc \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5\u060c \u067e\u06ce\u06cc\u0627\u0646\u062f\u0627 \u0628\u0686\u06c6\u0631\u06d5\u0648\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u0628\u06d5 \u06cc\u06d5\u06a9 \u06a9\u0631\u062a\u06d5 \u067e\u06ce\u0634\u06cc\u0627\u0646 \u0628\u062e\u06d5. \u0648\u06ce\u0646\u06d5 \u0626\u06d5\u0648\u06d5 \u0646\u0627\u0633\u06d5\u0644\u0645\u06ce\u0646\u06ce\u062a \u06a9\u06d5 \u06a9\u0627\u0631\u06d5\u06a9\u06d5 \u0644\u06d5\u0644\u0627\u06cc \u062a\u06d5\u06a9\u0646\u06cc\u0634\u06cc\u06d5\u0646\u06d5\u06a9\u06d5 \u0628\u0648\u0648\u06d5\u060c \u0628\u06c6\u06cc\u06d5 \u06a9\u0648\u0698\u0627\u0648\u06d5 \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5 \u062a\u0627 \u062e\u06c6\u062a \u0647\u06d5\u06b5\u06cc\u0628\u06a9\u06d5\u06cc\u062a."},
gJ0(){return"\u062c\u06c6\u0631\u06cc \u06a9\u06d5\u06cc\u0633 \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5."},
aay(a){return"\u062f\u062f\u0627\u0646\u06d5\u06a9\u0627\u0646 \u0628\u06c6 "+a+" \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u06d5."},
aaw(a){return"\u0695\u06d5\u0646\u06af \u0628\u06c6 "+a+" \u0647\u06d5\u06b5\u0628\u0698\u06ce\u0631\u06d5 (\u06cc\u0627\u0646 \xab\u062f\u0648\u0627\u062a\u0631 \u062f\u06cc\u0627\u0631\u06cc \u062f\u06d5\u06a9\u0631\u06ce\u062a\xbb)."},
gNi(){return"\u0633\u06d5\u0631\u062f\u06ce\u0695\u06cc \u0646\u0627\u0648\u06d5\u0695\u0627\u0633\u062a \u0644\u06d5 \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u0627\u0646\u062f\u0627"},
gNh(){return"\u0626\u06d5\u06af\u06d5\u0631 \u06a9\u0627\u0631\u0627 \u0628\u06ce\u062a: \u0646\u0627\u0648 \u0648 \u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5 \u0644\u06d5 \u0646\u0627\u0648\u06d5\u0695\u0627\u0633\u062a\u06cc \u0633\u06d5\u0631\u06d5\u0648\u06d5\u06cc \u067e\u0633\u0648\u0648\u0644\u06d5 \u0648 \u0644\u06cc\u0633\u062a\u06cc \u06a9\u06d5\u06cc\u0633 \u0648 \u06a9\u06d5\u0634\u0641\u06cc \u062d\u0633\u0627\u0628\u062f\u0627 \u062f\u06d5\u0628\u0646\u060c \u0648 \u0646\u0627\u0648\u0646\u06cc\u0634\u0627\u0646 \u0648 \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u0628\u06d5\u06b5\u06af\u06d5\u0646\u0627\u0645\u06d5\u06a9\u06d5 \u0644\u06d5 \u0646\u0627\u0648\u06d5\u0695\u0627\u0633\u062a\u062f\u0627 \u0644\u06d5 \u0698\u06ce\u0631\u06cc\u0627\u0646\u062f\u0627."},
