gafl(){return"\u06a4\u06ce \u0644\u06cc\u0646\u06a9\u06ce \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u0646 \u062e\u06c6 \u0628\u0641\u0631\u06ce\u06a9\u06d5. \xab\u062f\u06d5\u0633\u062a\u067e\u06ce\u06a9\u0631\u0646\xbb \u062f\u0627\u062f\u06af\u0631\u0646 \u0648 \u0698\u0645\u0627\u0631\u0627 \u062a\u06d5\u0644\u06d5\u0641\u06c6\u0646\u0627 \u062e\u06c6 \u067e\u0627\u0631\u06a4\u06d5 \u062f\u06a9\u06d5\u0646\u061b \u0628\u06c6\u062a \u0628 \u0648\u06ce \u0698\u0645\u0627\u0631\u0627 \u0644 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u0627\u0646 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u06cc \u0648\u0627\u0646 \u062f\u0646\u06cc\u0627\u0633\u06cc\u062a."},
gafj(){return"\u0628\u06c6 \u0648\u06d5\u0631\u06af\u0631\u062a\u0646\u0627 \u0646\u0627\u0645\u06d5\u06cc\u06ce \u0628\u06c6 \u0647\u06d5\u0631 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u06ce \u062f\u06a9\u062a\u06c6\u0631 \u062f\u0641\u0631\u06ce\u06a9\u06d5\u0646\u060c \u0628\u06c6\u062a\u06cc \u06a4\u06d5\u06a9\u06d5 \u0648 \u0628\u0641\u0631\u06ce\u06a9\u06d5:"},
gafk(){return"\u06a9\u06c6\u062f\u06d5\u06a9\u06ce \u0646\u0648\u0648"},
afc(a){return"\u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0698 \u0628\u06c6\u062a\u06cc \u0628 \u0646\u0627\u06a4\u06ce "+a+" \u062f\u0647\u06ce\u0646\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u0646."},
gaff(){return"\u0698\u06ce\u06a4\u06d5\u06a9\u0631\u0646\u0627 \u0628\u06c6\u062a\u06cc"},
gafh(){return"\u0628\u06c6\u062a \u0628\u0647\u06ce\u062a\u06d5 \u0698\u06ce\u06a4\u06d5\u06a9\u0631\u0646\u061f"},
afg(a){return a+" \u062f\u06ce \u0686\u06cc\u062f\u06cc \u0628\u06d5\u0631\u0633\u06a4\u06ce \u0646\u06d5\u062f\u06d5\u062a \u0648 \u06af\u0631\u06ce\u062f\u0627\u0646\u0627 \u0647\u06d5\u0645\u06cc \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646 \u062f\u06ce \u0647\u06ce\u062a\u06d5 \u0698\u06ce\u0628\u0631\u0646. \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0628\u06d5\u0631\u06cc \u0646\u0648\u06a9\u06d5 \u0647\u0627\u062a\u06cc\u0646\u06d5 \u0641\u0631\u06ce\u06a9\u0631\u0646 \u0644 IQ Labs \u062f\u0645\u06cc\u0646\u0646."},
gGx(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u067e\u06c6\u0644\u06ce"},
gZq(){return"\u0646\u0627\u06a4\u06ce \u067e\u06c6\u0644\u06ce"},
gZP(){return"\u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc\u06a9\u0631\u0646\u0627 \u067e\u06c6\u0644\u06ce"},
gZf(){return"\u067e\u06c6\u0644"},
gZr(){return"\u0628\u06ce \u067e\u06c6\u0644"},
gGL(){return"\u0628\u06ce \u067e\u06c6\u0644"},
ZK(a){return"\u062a\u0648 \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06cc \u062f\u06ce \u067e\u06c6\u0644\u0627 \xab"+a+"\xbb \u0698\u06ce\u0628\u0628\u06d5\u06cc\u061f"},
gZJ(){return"\u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f \u0646\u0627\u06a4\u062f\u0627 \u062f\u0645\u06cc\u0646\u0646 \u0648 \u062f\u0686\u0646\u06d5 \xab\u0628\u06ce \u067e\u06c6\u0644\xbb."},
gac_(){return"\u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631\u06a9\u0631\u0646 \u0628 \u067e\u06c6\u0644\u06ce\u0646 \u062c\u06c6\u0631\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646"},
gabZ(){return"\u0628\u06c6 \u062f\u06d5\u0633\u062a\u067e\u06ce\u06af\u06d5\u0647\u0634\u062a\u0646\u0627 \u062a\u06d5\u0645\u0627\u0645 \u06a4\u0627\u0644\u0627 \u0628\u0647\u06ce\u0644\u06d5. \u067e\u06c6\u0644\u06d5\u06a9\u06ce \u06cc\u0627\u0646 \u0632\u06ce\u062f\u06d5\u062a\u0631 \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 \u0648 \u0626\u06d5\u06a4 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u06ce \u062a\u0646\u06ce \u06a9\u06d5\u06cc\u0633\u06ce\u0646 \u0648\u0627\u0646 \u067e\u06c6\u0644\u0627\u0646 \u0628\u06cc\u0646\u06cc\u062a \u0648 \u06a9\u0627\u0631\u06ce \u0644 \u0633\u06d5\u0631 \u06a9\u06d5\u062a\u060c \u062f \u0647\u06d5\u0645\u06cc \u0628\u06d5\u0634\u06ce\u0646 \u0626\u06d5\u067e\u06cc \u062f\u0627. \u0628\u06d5\u0695\u06ce\u06a4\u06d5\u0628\u06d5\u0631 \u0686 \u062c\u0627\u0631\u0627\u0646 \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631 \u0646\u0627\u0628\u06cc\u062a. \u062f\u06d5\u0633\u062a\u067e\u06ce\u06af\u06d5\u0647\u0634\u062a\u0646\u0627 \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u0627\u0646 \u06cc\u0627\u0646 \u0695\u0627\u067e\u06c6\u0631\u062a\u0627\u0646 \u0646\u06d5\u062f\u06d5 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06ce \u0633\u0646\u0648\u0648\u0631\u062f\u0627\u0631: \u06a9\u06c6\u06a9\u0631\u0627\u0648\u06ce\u0646 \u0648\u06cc \u062a\u0646\u06ce \u0626\u06d5\u0648 \u067e\u06c6\u0644 \u062f\u06af\u0631\u0646."},
P3(a,b){return"\u062c\u0647\u06ce \u0628\u06a9\u0627\u0631\u0647\u0627\u062a\u06cc: "+a+" \u0698 "+b+" GB \u06cc\u06ce\u0646 \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631"},
P2(a,b,c){return""+a+" GB \u062f\u06af\u06d5\u0644 \u0628\u06d5\u0634\u062f\u0627\u0631\u0628\u0648\u0648\u0646\u06ce \u062f\u0627\u0646\u06d5. \u067e\u0634\u062a\u06cc \u0648\u06ce\u060c "+b+" \u0628\u06c6 \u0647\u06d5\u0631 100 GB \u062f \u0633\u0627\u0644\u06ce \u062f\u0627\u060c \u0644 \u062f\u0648\u06cc\u06a4 \u062a\u06ce\u06a9\u0695\u0627\u06cc\u0627 \u0628\u06a9\u0627\u0631\u0626\u06cc\u0646\u0627\u0646\u0627 \u062a\u06d5 \u062f \u0661\u0662 \u0647\u06d5\u06cc\u06a4\u06ce\u0646 \u0628\u0648\u0631\u06cc \u062f\u0627 (\u0646\u0648\u06a9\u06d5 "+c+")."},
P1(a){return"\u062a\u06ce\u0686\u0648\u0648\u06cc\u0627 \u0647\u06cc\u06a4\u06cc\u06a9\u0631\u06cc \u06cc\u0627 \u062c\u0647\u06ce \u067e\u0627\u0631\u0627\u0633\u062a\u0646\u06ce \u0628\u06c6 \u06a4\u06ce \u0633\u0627\u0644\u06ce: "+a},
gYq(){return"\u0641\u0631\u06ce\u06a9\u0631\u0646"},
Yr(a){return"\u0647\u0627\u062a\u06d5 \u0641\u0631\u06ce\u06a9\u0631\u0646 "+a},
