gafB(){return"\u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc (\u0686\u0627\u067e\u062e\u0627\u0646\u06d5\u060c \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u0645\u06cc\u0644\u06cc\u0646\u06af\u06ce\u2026)"},
gafA(){return"\u062f\u0648\u06af\u0645\u06ce \xab\u0641\u0631\u06ce\u06a9\u0631\u0646\xbb \u0644 \u067e\u06d5\u0695\u06ce \u06a9\u06d5\u06cc\u0633\u06cc \u0628 \u0626\u06ce\u06a9 \u062f\u0627\u06af\u0631\u062a\u0646 \u06a9\u0627\u063a\u06d5\u0632\u0627 \u06a9\u06d5\u06cc\u0633\u06cc \u0628\u06c6 \u06a4\u0627\u0646 \u0686\u0627\u062a\u06ce\u0646 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u0641\u0631\u06ce\u06a9\u06d5\u062a."},
gafz(){return"\u0647\u06ce\u0634\u062a\u0627 \u0686 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc \u0646\u06cc\u0646\u0646."},
gK3(){return"\u0632\u06ce\u062f\u06d5\u06a9\u0631\u0646\u0627 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06ce"},
gafu(){return"\u0646\u0627\u06a4 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5: \u0686\u0627\u067e\u062e\u0627\u0646\u06d5)"},
